/* Real-prototype augmentation for chpass's own build (DAR-174) -- NOT a
 * replacement for libc_build/compat_include/libutil.h (that file is
 * shared/generated by build_simple_cmds.sh for `ls`'s own strmode()/
 * humanize_number() needs; editing it from here would risk breaking
 * that unrelated consumer). This directory is listed EARLIER on
 * build_chpass.sh's own -I line than libc_build/compat_include, so
 * chpass.c's/edit.c's real `#include <libutil.h>` picks up THIS file
 * first; #include_next below chains to the real shared one afterward
 * so nothing `ls` needs is lost.
 *
 * Prototypes below match chpass_pw_util_freebsd.c's own real function
 * signatures exactly (that file is the real, adapted FreeBSD
 * lib/libutil/pw_util.c -- see its own header for the full citation).
 */
#ifndef _CHPASS_LIBUTIL_PW_AUGMENT_H_
#define _CHPASS_LIBUTIL_PW_AUGMENT_H_

#include_next <libutil.h>

#include <sys/types.h>
#include <stdio.h>
struct passwd;

int	 pw_init(const char *dir, const char *master);
int	 pw_lock(void);
int	 pw_tmp(int mfd);
int	 pw_mkdb(const char *user);
int	 pw_edit(int notsetuid);
void	 pw_fini(void);
int	 pw_equal(const struct passwd *pw1, const struct passwd *pw2);
char	*pw_make(const struct passwd *pw);
const char *pw_tempname(void);
struct passwd *pw_dup(const struct passwd *pw);

/* flopen()/flopenat() -- real FreeBSD prototypes (chpass_flopen_freebsd.c),
 * pw_lock() above's own real dependency. */
int	 flopen(const char *path, int flags, ...);
int	 flopenat(int dirfd, const char *path, int flags, ...);

/* pw_scan()/pw_initpwd() -- real FreeBSD lib/libutil/pw_util.c's own
 * public wrappers (defined in chpass_pw_scan_freebsd.c, which see for
 * the full citation). PWSCAN_MASTER/PWSCAN_WARN are the real FreeBSD
 * lib/libutil/libutil.h public aliases of pw_scan.h's own
 * _PWSCAN_MASTER/_PWSCAN_WARN (confirmed via a real `git show` against
 * this project's own pinned third_party/freebsd-src @ release/13.2.0)
 * -- edit.c's own real verify() calls `pw_scan(buf, PWSCAN_WARN|
 * PWSCAN_MASTER)` using these unprefixed names specifically. */
struct passwd	*pw_scan(const char *line, int flags);
void		 pw_initpwd(struct passwd *pw);
#define PWSCAN_MASTER	0x01
#define PWSCAN_WARN	0x02

/* _PWF_SOURCE/_PWF_FILES/_PWF_NIS -- real FreeBSD include/pwd.h private
 * struct-passwd-source bits (confirmed via the same real `git show`).
 * chpass.c's own real, unmodified non-OPEN_DIRECTORY tail references
 * `pw->pw_fields` -- real Apple struct passwd (this project's iPhoneOS
 * SDK pwd.h) has no such member at all (private Darwin/BSD extension,
 * confirmed absent via direct read). The #define below redirects that
 * one dead reference to reuse pw_gid's storage -- PROVEN SAFE, not a
 * guess: chpass_pw_scan_freebsd.c's own header shows pw_fields is
 * write-only in real __pw_scan (never read back within it), and
 * chpass.c's own only READER of pw_fields sits immediately after an
 * unconditional `exit(0);` (chpass.c line 388, checked directly) that
 * makes the whole block provably unreachable in this build. Scoped to
 * chpass's own -I search order only (this directory is listed first);
 * none of this project's other pw_util-family files (vipw/passwd/
 * pwd_mkdb) see this macro. */
#define _PWF_SOURCE	0x3000
#define _PWF_FILES	0x1000
#define _PWF_NIS	0x2000
#define pw_fields pw_gid

/* pw_copy() -- chpass.c's own real, unmodified call site (inside the
 * same provably-dead post-`exit(0)` block discussed above) calls
 * `pw_copy(pfd, tfd, pw, old_pw) == -1` -- FOUR arguments, int return
 * checked against -1 -- but this project's real chpass.tproj/pw_copy.c
 * (already built, see build_chpass.sh) defines pw_copy as
 * `void pw_copy(int ffd, int tfd, struct passwd *pw)` -- THREE args,
 * void return (confirmed by reading it directly; pw_copy.h agrees).
 * The call site's real shape (4 args, int-returning) instead matches
 * real FreeBSD's OWN lib/libutil/pw_util.c pw_copy() exactly (confirmed
 * via a real `git show` against this project's pinned freebsd-src) --
 * chpass.c was evidently written against that API and never reconciled
 * with this checkout's own different, Apple-specific 3-arg/void
 * pw_copy.c. Two real, confirmed mismatches in Apple's own pinned
 * source, not introduced here. Because the call site is unreachable
 * (see above), neither mismatch ever actually executes; this prototype
 * exists only so the call COMPILES, matching the call site's own real
 * shape rather than pw_copy.c's. Not "fixed" by changing pw_copy.c
 * itself -- that stays real and unmodified. */
int	 pw_copy(int ffd, int tfd, struct passwd *pw, struct passwd *old_pw);

#endif
